1	import { type ValidationResult, type Validator, ArchitectureManifest } from '../core/models.js';
2	
3	/**
4	 * ArchitecturalValidator - Enforces core architectural constraints.
5	 */
6	export class ArchitecturalValidator implements Validator {
7	    readonly name = 'ArchitecturalValidator';
8	
9	    constructor(private readonly manifest: ArchitectureManifest) { }
10	
11	    async validate(output: string, context?: { fileName?: string }): Promise<ValidationResult> {
12	        // 1. Illegal Dependency Check
13	        const imports = this.extractImports(output);
14	        for (const imp of imports) {
15	            if (this.isIllegalDependency(imp, context?.fileName)) {
16	                return {
17	                    ok: false,
18	                    error: {
19	                        reason: `Illegal dependency "${imp}" in ${context?.fileName || 'unknown'}.`,
20	                        suggestion: `Check the Architecture Manifest for allowed dependencies.`
21	                    }
22	                };
23	            }
24	        }
25	
26	        // 2. Primary Goal Alignment (e.g. NO MOCKS)
27	        if (this.violatesPrimaryGoal(output)) {
28	            return {
29	                ok: false,
30	                error: {
31	                    reason: `Violation of primary goal: ${this.manifest.primaryGoal}`,
32	                    suggestion: `Remove mocks or faked logic and implement real Sovereign code.`
33	                }
34	            };
35	        }
36	
37	        return { ok: true, value: true };
38	    }
39	
40	    private extractImports(content: string): string[] {
41	        const pattern = /import\s+.*from\s+['"](.*)['"]/g;
42	        const imports: string[] = [];
43	        let match;
44	        while ((match = pattern.exec(content)) !== null) {
45	            if (match[1]) imports.push(match[1]);
46	        }
47	        return imports;
48	    }
49	
50	    private isIllegalDependency(imp: string, currentFile?: string): boolean {
51	        if (!currentFile) return false;
52	        // Simple layer check
53	        const layerMatch = currentFile.match(/src\/([^/]+)/);
54	        if (!layerMatch) return false;
55	        const currentLayer = layerMatch[1]!.toLowerCase();
56	
57	        const allowed = this.manifest.dependencyRules[currentLayer] || [];
58	
59	        // Detect target layer
60	        const targetMatch = imp.match(/(\.\.\/|src\/)([^/]+)\//);
61	        if (!targetMatch) return false;
62	        const targetLayer = targetMatch[2]!.toLowerCase();
63	
64	        if (targetLayer !== currentLayer && !allowed.includes(targetLayer)) {
65	            return true;
66	        }
67	        return false;
68	    }
69	
70	    private violatesPrimaryGoal(output: string): boolean {
71	        if (this.manifest.primaryGoal.includes('NO MOCKS')) {
72	            const forbidden = [/jest\.fn/, /vi\.fn/, /sinon\.stub/, /mock\(/];
73	            return forbidden.some(p => p.test(output));
74	        }
75	        return false;
76	    }
77	
78	    /**
79	     * Phase 29: Function-Deletion Guard.
80	     * Extracts all exported symbols (functions, classes, consts, types, enums, interfaces)
81	     * from the original code and verifies they ALL survive in the modified version.
82	     * The system must NEVER heal by deletion.
83	     */
84	    public validatePreservation(original: string, modified: string): ValidationResult {
85	        const originalSymbols = this.extractExportedSymbols(original);
86	        const modifiedSymbols = this.extractExportedSymbols(modified);
87	
88	        const deleted: string[] = [];
89	        for (const sym of originalSymbols) {
90	            if (!modifiedSymbols.has(sym)) {
91	                deleted.push(sym);
92	            }
93	        }
94	
95	        if (deleted.length > 0) {
96	            return {
97	                ok: false,
98	                error: {
99	                    reason: `Function-Deletion Guard: ${deleted.length} exported symbol(s) were removed: [${deleted.join(', ')}]. The system must NEVER heal by deletion.`,
100	                    suggestion: `Restore the deleted symbols and fix them in-place instead. Young/Old snapshot will be used for rollback.`
101	                }
102	            };
103	        }
104	
105	        return { ok: true, value: true };
106	    }
107	
108	    /**
109	     * Extracts all exported symbol names from TypeScript source code.
110	     * Covers: export function, export class, export const, export let,
111	     *         export type, export interface, export enum, export default,
112	     *         and re-exports like export { X }.
113	     */
114	    private extractExportedSymbols(content: string): Set<string> {
115	        const symbols = new Set<string>();
116	
117	        // export function/class/const/let/type/interface/enum NAME
118	        const declarationPattern = /export\s+(?:async\s+)?(?:function|class|const|let|var|type|interface|enum)\s+(\w+)/g;
119	        let match;
120	        while ((match = declarationPattern.exec(content)) !== null) {
121	            if (match[1]) symbols.add(match[1]);
122	        }
123	
124	        // export default function/class NAME
125	        const defaultPattern = /export\s+default\s+(?:async\s+)?(?:function|class)\s+(\w+)/g;
126	        while ((match = defaultPattern.exec(content)) !== null) {
127	            if (match[1]) symbols.add(match[1]);
128	        }
129	
130	        // export { A, B, C } â€” named re-exports
131	        const bracePattern = /export\s*\{([^}]+)\}/g;
132	        while ((match = bracePattern.exec(content)) !== null) {
133	            if (match[1]) {
134	                const names = match[1].split(',').map(n => n.trim().split(/\s+as\s+/)[0]?.trim()).filter(Boolean);
135	                names.forEach(n => { if (n) symbols.add(n); });
136	            }
137	        }
138	
139	        return symbols;
140	    }
141	
142	    public healthCheck(): { online: boolean; details: string } {
143	        return { online: true, details: 'ArchitecturalValidator clinical enforcement substrate active. Function-deletion guard armed.' };
144	    }
145	}
