1	/**
2	 * AvatarCompositionEngine.ts
3	 * 
4	 * Bridges the SovereignAvatarEntity to the RSMV cache-grounded avatar pipeline.
5	 * Uses the real 16-slot avatar encoding from RSMV/3d/avatar.ts, identity kit
6	 * definitions, and Jagex's HSL color replacement system.
7	 * 
8	 * This engine does NOT fabricate schemas — it consumes the cache substrate directly
9	 * through EngineCache and the avatar parser (avatarToModel, writeAvatar).
10	 * 
11	 * Slot layout (from cache):
12	 *   0:helm 1:cape 2:necklace 3:weapon 4:body 5:offhand 6:arms 7:legs
13	 *   8:face 9:gloves 10:boots 11:beard 12:ring 13:ammo 14:aura 15:slot15
14	 *
15	 * Kit body parts (male): 0:head 1:jaw/beard 2:body 3:arms 4:hands 5:legs 6:feet
16	 * Kit body parts (female): 7:head 9:body 10:arms 11:hands 12:legs 13:feet
17	 */
18	
19	import { Result } from '../core/models.js';
20	import { SovereignAvatarEntity } from '../core/SovereignAvatar.js';
21	import { slotNames, slotToKitMale, slotToKitFemale, avatarToModel, writeAvatar, avatarStringToBytes, bytesToAvatarString } from 'rsmv/3d/avatar.js';
22	import type { EquipSlot } from 'rsmv/3d/avatar.js';
23	export type SimpleModelDef = {
24	    modelid: number;
25	    mods: any;
26	    injectedModelData?: any;
27	}[];
28	export type EngineCache = any;
29	import type { avataroverrides } from '../generated/avataroverrides.js';
30	
31	// ═══════════════════════════════════════════════════════
32	// Types
33	// ═══════════════════════════════════════════════════════
34	
35	/** Result from a full avatar composition pass */
36	export interface ComposedAvatarResult {
37	    models: SimpleModelDef;
38	    anims: Record<string, number>;
39	    avatar: avataroverrides | null;
40	    gender: number;
41	    /** Base64-encoded avatar string for network sync */
42	    avatarString: string;
43	    mode?: string;
44	}
45	
46	/** Minimal avatar identity for GlobeState sync */
47	export interface AvatarIdentitySync {
48	    avatarString: string;
49	    gender: number;
50	    isNpc: boolean;
51	    npcId?: number;
52	    mode?: string;
53	}
54	
55	// ═══════════════════════════════════════════════════════
56	// AvatarCompositionEngine
57	// ═══════════════════════════════════════════════════════
58	
59	export class AvatarCompositionEngine {
60	    private engineCache: EngineCache | null = null;
61	
62	    /**
63	     * Bind to a live EngineCache instance. Required before any composition calls.
64	     * This is the real rsmv cache substrate, not a mock.
65	     */
66	    public bindCache(cache: EngineCache): void {
67	        this.engineCache = cache;
68	    }
69	
70	    /**
71	     * Compose a full avatar model from a raw avatar buffer (from cache or network).
72	     * Delegates entirely to the rsmv avatarToModel parser which handles:
73	     *   - 16-slot equipment/kit tree search
74	     *   - Identity kit body part resolution
75	     *   - HSL color replacement (skin, hair, clothes, boots)
76	     *   - Animation group resolution via struct prop 2954
77	     *   - NPC appearance override (0xFFFF npc buzz)
78	     */
79	    public async composeFromBuffer(buffer: Buffer, head: boolean = false, mode?: string): Promise<Result<ComposedAvatarResult>> {
80	        if (!this.engineCache) {
81	            return { ok: false, error: new Error('EngineCache not bound. Call bindCache() first.') };
82	        }
83	
84	        try {
85	            // Pass the mode flag down to the RSMV renderer so it respects the template's era (e.g., 'classic', 'beta')
86	            const result = await avatarToModel(this.engineCache, buffer, head, mode as any);
87	            return {
88	                ok: true,
89	                value: {
90	                    models: result.models,
91	                    anims: result.anims,
92	                    avatar: result.info?.avatar ?? null,
93	                    gender: result.info?.gender ?? 0,
94	                    avatarString: bytesToAvatarString(buffer),
95	                    mode
96	                }
97	            };
98	        } catch (error) {
99	            return { ok: false, error: error instanceof Error ? error : new Error(String(error)) };
100	        }
101	    }
102	
103	    /**
104	     * Compose from a base64 avatar string (the format used by Jagex's avatar endpoint
105	     * and the GlobeState sync protocol).
106	     */
107	    public async composeFromAvatarString(avatarStr: string, head: boolean = false, mode?: string): Promise<Result<ComposedAvatarResult>> {
108	        try {
109	            const buffer = avatarStringToBytes(avatarStr);
110	            return this.composeFromBuffer(buffer, head, mode);
111	        } catch (error) {
112	            return { ok: false, error: error instanceof Error ? error : new Error(String(error)) };
113	        }
114	    }
115	
116	    /**
117	     * Build an AvatarIdentitySync payload from a SovereignAvatarEntity.
118	     * This is the minimal identity needed for GlobeState multiplayer sync.
119	     */
120	    public buildIdentitySync(avatar: SovereignAvatarEntity): AvatarIdentitySync {
121	        // The avatar appearance buffer is what gets synced over the wire.
122	        // If no appearance data exists, return a default identity.
123	        return {
124	            avatarString: '', // Populated when avatar has been composed from cache
125	            gender: avatar.appearance?.gender === 'classic' ? 2 : (avatar.appearance?.gender === 'female' ? 1 : 0),
126	            isNpc: false,
127	            mode: avatar.appearance?.mode || 'beta', // Ensure template mode is passed through to renderer
128	        };
129	    }
130	
131	    /**
132	     * Get the cache-grounded slot names array (16 slots).
133	     * Useful for UI rendering and debugging.
134	     */
135	    public getSlotNames(): string[] {
136	        return [...slotNames];
137	    }
138	
139	    /**
140	     * Get the kit-to-slot mapping for a given gender.
141	     * Returns the cache-accurate body part → slot index mapping.
142	     */
143	    public getKitMapping(gender: 'male' | 'female' | 'classic'): Record<number, number> {
144	        return gender === 'female' ? { ...slotToKitFemale } : { ...slotToKitMale };
145	    }
146	
147	    public healthCheck(): Result<string> {
148	        const cacheStatus = this.engineCache ? 'BOUND' : 'UNBOUND';
149	        return {
150	            ok: true,
151	            value: `AvatarCompositionEngine: cache=${cacheStatus}, slots=${slotNames.length}`
152	        };
153	    }
154	}
