1	import { ShellEngine } from './ShellEngine.js';
2	import { PulseMonitor } from '../monitor/PulseMonitor.js';
3	import { type Result, ok, err, YaoState } from '../core/models.js';
4	import { StoryboardLimbV2, type StoryboardScene } from '../limbs/creative/StoryboardLimbV2.js';
5	import { createLogger } from '../utils/logger.js';
6	import { join } from 'path';
7	import { existsSync, writeFileSync } from 'fs';
8	import { getSovereignRoot } from '../utils/SovereignPathResolver.js';
9	
10	const logger = createLogger('BlenderRenderer');
11	
12	export interface RenderCost {
13	    ramBytes: number;
14	    cpuLoad: number;
15	    estimatedTimeSec: number;
16	}
17	
18	export interface Clip {
19	    path: string;
20	    duration: number;
21	    type: '3D_BLENDER' | '2D_GHOST';
22	}
23	
24	interface SubjectDirective {
25	    type: string;
26	    primitive: string;
27	}
28	
29	interface SceneAnalysis {
30	    subjects: SubjectDirective[];
31	    isDark: boolean;
32	    isFiery: boolean;
33	    isCinematic: boolean;
34	    isAerial: boolean;
35	    isPlayerPOV: boolean;
36	    hasMotion: boolean;
37	    keyColor: [number, number, number];
38	    frameCount: number;
39	    description: string;
40	    sceneIndex: number;
41	}
42	
43	export class BlenderRenderer {
44	    private readonly rendersDir = join(getSovereignRoot(), 'renders');
45	
46	    constructor(
47	        private readonly shell: ShellEngine,
48	        private readonly pulse: PulseMonitor,
49	        private readonly fallbackGen: (scene: StoryboardScene) => Promise<Result<{ path: string }>>
50	    ) {
51	        if (!existsSync(this.rendersDir)) {
52	            // mkdirSync(this.rendersDir, { recursive: true }); // Handled by shell if needed, but let's be safe
53	        }
54	    }
55	
56	    /**
57	     * render - High-fidelity 3D synthesis with metabolic safety.
58	     */
59	    public async render(scene: StoryboardScene, projectPath: string): Promise<Result<Clip>> {
60	        const memory = await this.pulse.checkMemoryHealth();
61	        if (memory.success) {
62	            const usagePercent = Number((memory.data.total - memory.data.free) * 100n / memory.data.total);
63	            if (usagePercent > 92) {
64	                logger.warn({ usagePercent }, 'Metabolic Overload: >92% RAM. Triggering Ghost Fallback (2D).');
65	                return this.fallbackTo2D(scene);
66	            }
67	            logger.info({ usagePercent }, 'Metabolic headroom confirmed for 3D render.');
68	        }
69	
70	        logger.info({ index: scene.index, description: scene.description }, 'Initiating Sovereign 3D Render.');
71	
72	        const scriptPath = join(projectPath, `render_scene_${scene.index}.py`);
73	        const videoPath = join(projectPath, `scene_${scene.index}.mp4`);
74	
75	        // Derive scene geometry and atmosphere from the storyboard description
76	        const sceneAnalysis = this.analyzeScene(scene);
77	        const pythonScript = this.generateCinemaScript(sceneAnalysis, videoPath);
78	        writeFileSync(scriptPath, pythonScript);
79	        logger.info({ scriptPath, bytes: pythonScript.length }, 'Cinema script written.');
80	
81	        const blenderPath = `"C:\\\\Program Files\\\\Blender Foundation\\\\Blender 5.0\\\\blender.exe"`;
82	        const renderCmd = `${blenderPath} --background --python "${scriptPath}"`;
83	
84	        const startTime = Date.now();
85	        const res = await this.shell.execute({
86	            command: renderCmd,
87	            cwd: projectPath,
88	            description: `3D Render Scene ${scene.index}`
89	        });
90	
91	        if (!res.ok) {
92	            logger.error({ error: res.error.message }, 'Blender Render Failed. Falling back to 2D.');
93	            return this.fallbackTo2D(scene);
94	        }
95	
96	        // Post-render verification: does the file actually exist?
97	        if (!existsSync(videoPath)) {
98	            logger.warn({ videoPath }, 'Blender exited clean but MP4 not found. Checking for frame output...');
99	            // Blender may write with suffix â€” check for any mp4 in the directory
100	            const { readdirSync } = await import('fs');
101	            const files = readdirSync(projectPath).filter(f => f.endsWith('.mp4'));
102	            if (files.length > 0) {
103	                const actualPath = join(projectPath, files[0]);
104	                logger.info({ actualPath }, 'Found rendered MP4 output.');
105	                const duration = (Date.now() - startTime) / 1000;
106	                return ok({ path: actualPath, duration, type: '3D_BLENDER' });
107	            }
108	            logger.error('No MP4 output found after render. Falling back to 2D.');
109	            return this.fallbackTo2D(scene);
110	        }
111	
112	        const duration = (Date.now() - startTime) / 1000;
113	        return ok({ path: videoPath, duration, type: '3D_BLENDER' });
114	    }
115	
116	    /**
117	     * analyzeScene - Extract rendering directives from scene description.
118	     */
119	    private analyzeScene(scene: StoryboardScene): SceneAnalysis {
120	        const combined = (scene.description + ' ' + (scene.visualPrompts?.[0] || '') + ' ' + (scene.cameraNotes || '')).toLowerCase();
121	        
122	        // Evolve: Detect injected geometry paths from ReimaginationEngine
123	        let injectedGeometry: string | null = null;
124	        const injectMatch = scene.description.match(/\[GEOMETRY_INJECT:(.*?)\]/);
125	        if (injectMatch) {
126	            injectedGeometry = injectMatch[1].trim();
127	        }
128	
129	        const subjects: SubjectDirective[] = [];
130	
131	        // Evolve: If geometry is injected, it becomes the primary subject.
132	        if (injectedGeometry) {
133	             subjects.push({ type: 'INJECTED', primitive: injectedGeometry });
134	        } else {
135	             // Retain original legacy generative parsing
136	             const subjectPatterns: [RegExp, string, string][] = [
137	                 [/dragon|kbd|wyrm|drake/i, 'DRAGON', 'mesh.primitive_cone_add'],
138	                 [/human|person|man|woman|knight|warrior|hero/i, 'HUMANOID', 'mesh.primitive_cylinder_add'],
139	                 [/tree|forest|wood/i, 'TREE', 'mesh.primitive_cone_add'],
140	                 [/castle|tower|building|dungeon/i, 'ARCHITECTURE', 'mesh.primitive_cube_add'],
141	                 [/sword|weapon|axe|blade/i, 'WEAPON', 'mesh.primitive_cylinder_add'],
142	                 [/fire|flame|lava|inferno/i, 'FIRE_EMITTER', 'mesh.primitive_ico_sphere_add'],
143	                 [/water|ocean|river|lake/i, 'WATER', 'mesh.primitive_plane_add'],
144	                 [/monster|beast|creature/i, 'CREATURE', 'mesh.primitive_ico_sphere_add'],
145	             ];
146	
147	             for (const [pattern, type, primitive] of subjectPatterns) {
148	                 if (pattern.test(combined)) {
149	                     subjects.push({ type, primitive });
150	                 }
151	             }
152	        }
153	
154	        // If nothing detected, default to abstract geometry
155	        if (subjects.length === 0) {
156	            subjects.push({ type: 'ABSTRACT', primitive: 'mesh.primitive_torus_add' });
157	        }
158	
159	        // Detect atmosphere
160	        const isDark = /dark|shadow|dungeon|night|cave|underground|gloomy|sinister/.test(combined);
161	        const isFiery = /fire|flame|lava|burn|inferno|volcanic|roar/.test(combined);
162	        const isCinematic = /cinematic|dramatic|epic|volumetric|4k/.test(combined);
163	        const isAerial = /aerial|fly|sky|above|panoramic/.test(combined);
164	        const isPlayerPOV = combined.includes('player') || combined.includes('npc pov');
165	
166	        // Detect motion keywords for camera animation style
167	        const hasMotion = /roar|swing|charge|attack|run|explode|burst|swirl/.test(combined);
168	
169	        // Derive color palette from description
170	        let keyColor: [number, number, number] = [0.8, 0.6, 0.3]; // warm default
171	        if (isFiery) keyColor = [1.0, 0.3, 0.05];
172	        else if (/ice|frost|cold|winter/i.test(combined)) keyColor = [0.2, 0.5, 1.0];
173	        else if (/poison|toxic|venom/i.test(combined)) keyColor = [0.1, 0.9, 0.2];
174	        else if (/royal|noble|magic/i.test(combined)) keyColor = [0.6, 0.1, 0.9];
175	        else if (/nature|forest|green/i.test(combined)) keyColor = [0.2, 0.7, 0.15];
176	
177	        // Frame count: more for cinematic, less for simple
178	        const frameCount = isCinematic ? 48 : (hasMotion ? 36 : 24);
179	
180	        return {
181	            subjects,
182	            isDark,
183	            isFiery,
184	            isCinematic,
185	            isAerial,
186	            isPlayerPOV,
187	            hasMotion,
188	            keyColor,
189	            frameCount,
190	            description: scene.description,
191	            sceneIndex: scene.index
192	        };
193	    }
194	
195	    /**
196	     * generateCinemaScript - Produce real Blender Python for the analyzed scene.
197	     */
