268	    /**
269	     * Converts Hex string to RGB tuple.
270	     * @param hex - The hexadecimal color string (e.g., "#RRGGBB" or "RRGGBB").
271	     * @returns A readonly RGB tuple.
272	     */
273	    public static hexToRgb(hex: HexColor): RGB {
274	        const cleanHex = hex.replace('#', '');
275	        const bigint = parseInt(cleanHex, 16);
276	        return [
277	            (bigint >> 16) & 255,
278	            (bigint >> 8) & 255,
279	            bigint & 255
280	        ];
281	    }
