283	    /**
284	     * Calculates Euclidean distance between two colors.
285	     * @param colorA - The first hexadecimal color string.
286	     * @param colorB - The second hexadecimal color string.
287	     * @returns The Euclidean distance between the two colors.
288	     */
289	    public static calculateDistance(colorA: HexColor, colorB: HexColor): number {
290	        const rgbA = this.hexToRgb(colorA);
291	        const rgbB = this.hexToRgb(colorB);
292	
293	        return Math.sqrt(
294	            Math.pow(rgbA[0] - rgbB[0], 2) +
295	            Math.pow(rgbA[1] - rgbB[1], 2) +
296	            Math.pow(rgbA[2] - rgbB[2], 2)
297	        );
298	    }
