54	        }
55	
56	        // Build prefix/suffix context window (Ã‚Â±50 lines)
57	        const contextStart = Math.max(0, params.line - 51);
58	        const contextEnd = Math.min(lines.length, params.line + 49);
59	        const prefix = lines.slice(contextStart, params.line - 1).join('\n');
60	        const currentLine = lines[params.line - 1] ?? '';
61	        const suffix = lines.slice(params.line, contextEnd).join('\n');
62	
63	        const cursorMark = currentLine.substring(0, params.column) + '<CURSOR>' + currentLine.substring(params.column);
