155	    private parseDuckDuckGoResults(html: string, count: number): SearchResult[] {
156	        const results: SearchResult[] = [];
157	        const resultRegex = /<div class="result[^"]*"[^>]*>[\s\S]*?<\/div>\s*<\/div>/gi;
158	        const matches = html.match(resultRegex) || [];
159	
160	        for (const resultHtml of matches.slice(0, count)) {
161	            try {
162	                const titleMatch = resultHtml.match(/<a[^>]*class="[^"]*result__a[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
163	                const urlMatch = resultHtml.match(/<a[^>]*href="([^"]*uddg[^"]*)"[^>]*class="[^"]*result__a/i) ||
164	                    resultHtml.match(/<a[^>]*href="([^"]*)"[^>]*class="[^"]*result__a/i);
165	                const snippetMatch = resultHtml.match(/<a[^>]*class="[^"]*result__snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/i);
166	
167	                if (titleMatch && urlMatch) {
168	                    const title = this.cleanHtml(titleMatch[1]!);
169	                    let url = this.cleanUrl(urlMatch[1]!);
170	                    const snippet = snippetMatch ? this.cleanHtml(snippetMatch[1]!) : '';
171	
172	                    if (url.includes('uddg=')) {
173	                        try {
174	                            const uddgMatch = url.match(/uddg=([^&]*)/);
175	                            if (uddgMatch) url = decodeURIComponent(uddgMatch[1]!);
176	                        } catch { }
177	                    }
178	                    results.push({ title, url, snippet });
179	                }
180	            } catch { }
181	        }
182	        return results;
183	    }
