220	    async search(params: SearchParams): Promise<Result<EngineOutput>> {
221	        if (!this.db) return { ok: false, error: new Error('DB not initialized') };
222	
223	        const hex = this.router.getHexagram();
224	        const yao = hex.getYaoState();
225	        const directive = this.router.getHexagram().getInterpretation().strategy;
226	
227	        // Metabolic Scaling of Search Parameters
228	        let topK = params.topK;
229	        let threshold = params.threshold ?? 0.0;
230	
231	        if (yao === YaoState.OldYang) {
232	            topK += 2; // Expansive discovery in high-metabolism states
233	            threshold = Math.max(0, threshold - 0.05);
234	            logger.info({ yao, directive }, 'Metabolic Scaling: Increasing search breadth (+2 topK, -0.05 threshold)');
235	        } else if (yao === YaoState.OldYin) {
236	            threshold = Math.min(1.0, threshold + 0.1); // Precision pruning in decay states
237	            logger.info({ yao, directive }, 'Metabolic Scaling: Increasing search precision (+0.1 threshold)');
238	        } else if (yao === YaoState.OldMixed) {
239	            logger.warn({ yao, directive }, 'Semantic Density Warning: Unstable substrate detected. Results may be incoherent.');
240	        }
241	
242	        const embedResult = await this.client.embed(params.query);
243	        if (!embedResult.ok) return embedResult as any;
244	
245	        const queryVec = embedResult.value;
246	
247	        const rows = this.db.prepare(
248	            'SELECT * FROM embeddings WHERE project_id = ? ORDER BY indexed_at DESC LIMIT 1000'
249	        ).all(params.projectId) as EmbeddingRow[];
250	
251	        if (rows.length === 0) {
252	            return {
253	                ok: true,
254	                value: {
255	                    output: `No indexed files found for project "${params.projectId}".`,
256	                    data: { results: [] }
257	                }
258	            };
259	        }
260	
261	        const scored = rows.map(row => {
262	            if (!row.embedding) return null;
263	            const storedVec = new Float32Array(row.embedding.buffer, row.embedding.byteOffset, row.embedding.byteLength / 4);
264	            const score = this.cosineSimilarity(queryVec, storedVec);
265	            return {
266	                path: row.path,
267	                score,
268	                snippet: row.snippet,
269	                metadata: JSON.parse(row.metadata || '{}')
270	            };
271	        }).filter((r): r is { path: string; score: number; snippet: string; metadata: any } => r !== null && r.score >= threshold);
272	
273	        scored.sort((a, b) => b.score - a.score);
274	        const top = scored.slice(0, topK);
275	
276	        const output = top.length > 0
277	            ? top.map((r, i) => `[${i + 1}] ${r.path} (score: ${r.score.toFixed(3)})\n    ${r.snippet}`).join('\n\n')
278	            : 'No results found above threshold';
279	
280	        return {
281	            ok: true,
282	            value: {
283	                output,
284	                data: { results: top, yaoState: yao, directive }
285	            }
286	        };
287	    }
