289	    async cluster(params: { projectId: string; clusters?: number }): Promise<Result<EngineOutput>> {
290	        if (!this.db) return { ok: false, error: new Error('DB not initialized') };
291	
292	        const rows = this.db.prepare(
293	            'SELECT path, embedding FROM embeddings WHERE project_id = ?'
294	        ).all(params.projectId) as any[];
295	
296	        if (rows.length < 2) return { ok: false, error: new Error('Not enough files to cluster') };
297	
298	        const k = params.clusters || 3;
299	        this.renderer.info(`Clustering ${rows.length} files into ${k} conceptual regions...`);
300	
301	        // Simple k-means heuristic for local Ollama speed
302	        const vectors = rows.map(r => new Float32Array(r.embedding.buffer, r.embedding.byteOffset, r.embedding.byteLength / 4));
303	        const centroids = vectors.slice(0, k); // Start with first K as centroids
304	        const assignments = new Array(vectors.length).fill(0);
305	
