388	
389	        // Ternary interpretation of similarity score
390	        const tier = score >= 0.85 ? 'Yang (Highly Similar)'
391	            : score >= 0.60 ? 'YinYang (Moderately Similar)'
392	                : 'Yin (Dissimilar)';
393	
394	        return {
395	            ok: true,
396	            value: {
397	                output: `Similarity: ${score.toFixed(4)} Ã¢â‚¬â€ ${tier}\n${params.fileA} Ã¢â€ â€ ${params.fileB}`,
