89	    private async executeSingleTask(assignment: TaskAssignment): Promise<TaskResult> {
90	        const startTime = Date.now();
91	
92	        const result = await this.client.call({
93	            model: assignment.model,
94	            prompt: assignment.task,
95	            systemPrompt: assignment.systemPrompt,
96	            temperature: assignment.temperature ?? 0.3
97	        });
98	
99	        const latency = Date.now() - startTime;
100	
101	        return {
102	            id: assignment.id,
103	            model: assignment.model,
104	            result: result.ok
105	                ? { ok: true, value: { output: result.value.response } }
106	                : { ok: false, error: result.error },
107	            latency
108	        };
109	    }
