156	    private formatCombinedResults(results: TaskResult[], totalLatency: number): EngineOutput {
157	        const outputs: string[] = [];
158	
159	        for (const r of results) {
160	            const status = r.result.ok ? 'Ã¢Å“â€œ' : 'Ã¢Å“â€”';
161	            outputs.push(`[${status}] ${r.id} (${r.model}) - ${r.latency}ms`);
162	            if (r.result.ok) {
163	                outputs.push(r.result.value.output);
164	            } else {
165	                outputs.push(`ERROR: ${r.result.error.message}`);
166	            }
167	            outputs.push('');
168	        }
169	
170	        return {
171	            output: outputs.join('\n'),
172	            data: {
173	                parallelResults: results.map(r => ({
174	                    id: r.id,
175	                    model: r.model,
176	                    latency: r.latency,
177	                    success: r.result.ok
178	                })),
179	                totalLatency
180	            }
181	        };
182	    }
