213	    private extractSubtasks(plan: string, originalTask: string): TaskAssignment[] {
214	        // Simple extraction - could be enhanced with JSON parsing
215	        const lines = plan.split('\n').filter(l => l.trim().startsWith('-') || l.trim().startsWith('1.') || l.trim().startsWith('2.'));
216	
217	        if (lines.length < 2) {
218	            // No clear subtasks, just execute original
219	            return [{
220	                id: 'implementation',
221	                model: this.config.codingFastModel,
222	                task: originalTask
223	            }];
224	        }
225	
226	        // Create up to 4 subtasks
227	        const subtasks: TaskAssignment[] = [];
228	        const models = [
229	            this.config.codingFastModel,
230	            this.config.codingHeavyModel,
231	            this.config.orchestratorModel,
232	            this.config.codingFastModel // reuse fast for 4th
233	        ];
234	
235	        for (let i = 0; i < Math.min(lines.length, 4); i++) {
236	            subtasks.push({
237	                id: `subtask_${i + 1}`,
238	                model: models[i] ?? this.config.codingFastModel,
239	                task: `Execute this subtask as part of larger goal:\nORIGINAL TASK: ${originalTask}\n\nYOUR SUBTASK: ${lines[i]}`,
240	                systemPrompt: 'You are a specialized coding assistant. Implement only your assigned subtask precisely.'
241	            });
242	        }
243	
244	        return subtasks;
245	    }
